"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import { initials } from "./mention"
import {
  useMentionInput,
  type UseMentionInputOptions,
} from "./use-mention-input"

export type MentionLayout = "compact" | "rich"

export interface MentionInputProps extends UseMentionInputOptions {
  label?: ReactNode
  hint?: ReactNode
  /** `compact` fits more people on screen; `rich` disambiguates duplicate names. */
  layout?: MentionLayout
  rows?: number
}

export const MentionInput = forwardRef<HTMLTextAreaElement, MentionInputProps>(
  function MentionInput(
    { label, hint, layout = "compact", rows = 3, className, id: idProp, ...rest },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useMentionInput({ ...rest, id })
    const {
      textareaProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      suggestions,
      open,
      activeIndex,
      select,
    } = api

    useImperativeHandle(
      ref,
      () =>
        textareaProps.ref.current ??
        ({ focus: () => textareaProps.ref.current?.focus() } as HTMLTextAreaElement),
      [textareaProps.ref],
    )

    const listId = `${id}-suggestions`

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        <div className="inputcn-relative">
          <textarea
            {...textareaProps}
            {...ariaProps}
            id={id}
            rows={rows}
            className="inputcn-textarea"
            // No role="combobox": ARIA 1.2 permits that role on <input>, not
            // on a multi-line control, and axe rejects it. A textarea is
            // already a textbox, which allows aria-activedescendant — so the
            // active option is announced, and the live region below reports
            // that suggestions appeared.
            aria-controls={open ? listId : undefined}
            aria-activedescendant={
              open ? `${id}-option-${activeIndex}` : undefined
            }
            aria-label={rest["aria-label"]}
            aria-labelledby={rest["aria-labelledby"]}
          />

          {open ? (
            <div className="inputcn-popover">
              <ul
                className="inputcn-popover-list"
                role="listbox"
                aria-label="People you can mention"
                id={listId}
              >
                {suggestions.map((p, i) => (
                  // role="presentation" so the option is a direct child of the
                  // listbox in the accessibility tree, as ARIA requires.
                  <li key={p.id} role="presentation">
                    <button
                      type="button"
                      role="option"
                      id={`${id}-option-${i}`}
                      aria-selected={i === activeIndex}
                      className={`inputcn-popover-item${layout === "rich" ? " inputcn-rich" : ""}`}
                      data-active={i === activeIndex ? "true" : undefined}
                      // Mouse-down would blur the textarea before the click
                      // lands, closing the list out from under the pointer.
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={() => select(p)}
                    >
                      {layout === "rich" ? (
                        <>
                          <span className="inputcn-avatar" aria-hidden="true">
                            {initials(p.name)}
                          </span>
                          <span className="inputcn-meta">
                            <span className="inputcn-meta-name">{p.name}</span>
                            <span className="inputcn-meta-detail">
                              @{p.handle}
                              {p.detail ? ` · ${p.detail}` : ""}
                            </span>
                          </span>
                          {p.badge ? (
                            <span className="inputcn-role">{p.badge}</span>
                          ) : null}
                        </>
                      ) : (
                        <>
                          <span className="inputcn-name">{p.name}</span>
                          <span className="inputcn-dial">@{p.handle}</span>
                        </>
                      )}
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}
        </div>

        {/* Announces that suggestions appeared, since the textarea cannot
            carry combobox semantics. Polite, so it never interrupts typing. */}
        <span className="inputcn-sr-only" role="status" aria-live="polite">
          {open
            ? `${suggestions.length} ${suggestions.length === 1 ? "person" : "people"} available`
            : ""}
        </span>

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import {
  useCallback,
  useMemo,
  useRef,
  useState,
  type ClipboardEvent,
  type KeyboardEvent,
} from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import {
  custom,
  maxLength as maxLengthRule,
  required as requiredRule,
  rules,
} from "@inputcn/core/validity"

import {
  EMPTY_MENTION,
  activeQuery,
  applyMention,
  makeValue,
  parsePastedMention,
  search,
  type MentionValue,
  type Person,
} from "./mention"

export interface MentionConstraints {
  maxLength?: number
  minMentions?: number
  /** Caps notification blast radius. */
  maxMentions?: number
}

export interface UseMentionInputOptions
  extends BaseFieldProps<MentionValue>,
    MentionConstraints {
  people: readonly Person[]
  /** Suggestions shown at once. Default 8. */
  limit?: number
}

export interface UseMentionInputResult extends UseFieldResult<MentionValue> {
  /** Suggestions for the query the caret is currently inside. */
  suggestions: Person[]
  open: boolean
  /** Index of the highlighted suggestion. */
  activeIndex: number
  select: (person: Person) => void
  close: () => void
  textareaProps: {
    ref: React.RefObject<HTMLTextAreaElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void
    onKeyDown: (e: KeyboardEvent<HTMLTextAreaElement>) => void
    onPaste: (e: ClipboardEvent<HTMLTextAreaElement>) => void
    onSelect: () => void
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
}

export function useMentionInput(
  options: UseMentionInputOptions,
): UseMentionInputResult {
  const {
    people,
    limit = 8,
    maxLength,
    minMentions,
    maxMentions,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const ruleList = useMemo<ReadonlyArray<Rule<MentionValue>>>(
    () =>
      rules<MentionValue>(
        requiredRule<MentionValue>(required),
        maxLength !== undefined && {
          rule: "maxLength",
          params: { maxLength },
          test: (v: MentionValue) => v.text.length <= maxLength,
        },
        minMentions !== undefined && {
          rule: "minItems",
          params: { minItems: minMentions },
          test: (v: MentionValue) => v.ids.length >= minMentions,
        },
        maxMentions !== undefined && {
          rule: "maxItems",
          params: { maxItems: maxMentions },
          test: (v: MentionValue) => v.ids.length <= maxMentions,
        },
        custom<MentionValue>(validate),
      ),
    [required, maxLength, minMentions, maxMentions, validate],
  )

  const field = useField<MentionValue>({
    component: "MentionInput",
    emptyValue: EMPTY_MENTION,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
    // FormData carries the text; ids are derivable and would be redundant.
    serialize: (v) => v.text,
  })

  const { value, setValue } = field
  const ref = useRef<HTMLTextAreaElement | null>(null)

  const [caret, setCaret] = useState(0)
  const [dismissed, setDismissed] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)

  const query = useMemo(
    () => (dismissed ? null : activeQuery(value.text, caret)),
    [dismissed, value.text, caret],
  )

  const suggestions = useMemo(
    () => (query ? search(people, query.query, limit) : []),
    [query, people, limit],
  )

  const open = query !== null && suggestions.length > 0

  const commit = useCallback(
    (text: string) => {
      // Ids are recomputed from the text every time, so editing a mention out
      // removes the notification with it.
      setValue(makeValue(text, people))
    },
    [setValue, people],
  )

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      if (disabled || readOnly) return
      setDismissed(false)
      setActiveIndex(0)
      setCaret(e.currentTarget.selectionStart ?? 0)
      commit(e.currentTarget.value)
    },
    [disabled, readOnly, commit],
  )

  // Arrow-key navigation must not move the caret while the picker is open, so
  // the textarea's own handling is suppressed.
  const onKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      if (!open) return
      if (e.key === "ArrowDown") {
        e.preventDefault()
        setActiveIndex((i) => Math.min(i + 1, suggestions.length - 1))
      } else if (e.key === "ArrowUp") {
        e.preventDefault()
        setActiveIndex((i) => Math.max(i - 1, 0))
      } else if (e.key === "Enter" || e.key === "Tab") {
        const pick = suggestions[activeIndex]
        if (!pick || !query) return
        e.preventDefault()
        const next = applyMention(value.text, query, pick)
        commit(next.text)
        setCaret(next.caret)
        setDismissed(false)
        setActiveIndex(0)
        requestAnimationFrame(() => {
          ref.current?.setSelectionRange(next.caret, next.caret)
        })
      } else if (e.key === "Escape") {
        e.preventDefault()
        setDismissed(true)
      }
    },
    [open, suggestions, activeIndex, query, value.text, commit],
  )

  const select = useCallback(
    (person: Person) => {
      if (!query || disabled || readOnly) return
      const next = applyMention(value.text, query, person)
      commit(next.text)
      setCaret(next.caret)
      setDismissed(false)
      setActiveIndex(0)
      ref.current?.focus()
      requestAnimationFrame(() => {
        ref.current?.setSelectionRange(next.caret, next.caret)
      })
    },
    [query, disabled, readOnly, value.text, commit],
  )

  const close = useCallback(() => setDismissed(true), [])

  // Keep the caret position current when the user clicks or arrows around, so
  // the picker opens for the mention they are actually inside.
  const onSelect = useCallback(() => {
    setCaret(ref.current?.selectionStart ?? 0)
  }, [])

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLTextAreaElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      const el = ref.current
      const start = el?.selectionStart ?? value.text.length
      const end = el?.selectionEnd ?? start
      const pasted = parsePastedMention(text, people)
      if (!pasted) return
      const next = value.text.slice(0, start) + pasted.text + value.text.slice(end)
      commit(next)
      const at = start + pasted.text.length
      setCaret(at)
      requestAnimationFrame(() => el?.setSelectionRange(at, at))
    },
    [disabled, readOnly, value.text, people, commit],
  )

  const textareaProps = useMemo(
    () => ({
      ref,
      value: value.text,
      onChange,
      onKeyDown,
      onPaste,
      onSelect,
      disabled,
      readOnly,
      placeholder: placeholder ?? "Type @ to mention someone…",
    }),
    [value.text, onChange, onKeyDown, onPaste, onSelect, disabled, readOnly, placeholder],
  )

  return { ...field, suggestions, open, activeIndex, select, close, textareaProps }
}

/**
 * Mention parsing. Framework-free.
 *
 * Canonical value is `{ text, ids }` — the text as written, plus the ids of
 * everyone actually mentioned in it. Both matter: the text is what you render,
 * the ids are who you notify, and deriving one from the other at send time is
 * how people get notified for a mention that was edited away.
 */

import { scrub } from "@inputcn/core/paste"

export interface Person {
  id: string
  /** Display name. */
  name: string
  /** The @handle, without the "@". */
  handle: string
  /** Optional secondary line — team, role, email. */
  detail?: string
  /** Optional badge, e.g. "Owner". */
  badge?: string
}

export interface MentionValue {
  text: string
  /** Ids present in `text`, in first-appearance order, de-duplicated. */
  ids: string[]
}

export const EMPTY_MENTION: MentionValue = Object.freeze({ text: "", ids: [] })

/** Where an active `@query` sits in the text, if the caret is inside one. */
export interface ActiveQuery {
  /** Index of the "@". */
  start: number
  /** Index just past the query, i.e. the caret. */
  end: number
  /** The text between "@" and the caret. */
  query: string
}

// Handles are conservative on purpose: letters, digits, dot, dash, underscore.
// Anything looser starts swallowing punctuation that ends a sentence.
const HANDLE_CHAR = /[\w.-]/

/**
 * Find the mention query the caret is currently inside.
 *
 * Returns null when the caret is not after an "@", or when whitespace
 * intervenes — so "email me @ 5pm" never opens the picker.
 */
export function activeQuery(text: string, caret: number): ActiveQuery | null {
  const at = text.lastIndexOf("@", Math.max(0, caret - 1))
  if (at === -1) return null

  // An "@" only starts a mention at a word boundary, so "user@example.com"
  // does not trigger the picker.
  if (at > 0 && HANDLE_CHAR.test(text[at - 1]!)) return null

  const between = text.slice(at + 1, caret)
  if (between.length > 0 && !/^[\w.-]*$/.test(between)) return null

  return { start: at, end: caret, query: between }
}

/** Filter people by name or handle, ranked so prefix matches come first. */
export function search(people: readonly Person[], query: string, limit = 8): Person[] {
  const q = query.trim().toLowerCase()
  if (!q) return people.slice(0, limit)

  const prefix: Person[] = []
  const contains: Person[] = []

  for (const p of people) {
    const name = p.name.toLowerCase()
    const handle = p.handle.toLowerCase()
    if (handle.startsWith(q) || name.startsWith(q)) prefix.push(p)
    else if (handle.includes(q) || name.includes(q)) contains.push(p)
  }

  return [...prefix, ...contains].slice(0, limit)
}

/** Replace the active query with a chosen handle. Returns text and new caret. */
export function applyMention(
  text: string,
  active: ActiveQuery,
  person: Person,
): { text: string; caret: number } {
  const before = text.slice(0, active.start)
  const after = text.slice(active.end)
  // A trailing space is what lets the user keep typing without it becoming
  // part of the handle.
  const inserted = `@${person.handle} `
  return { text: before + inserted + after, caret: before.length + inserted.length }
}

/**
 * True when position `i` ends a handle.
 *
 * Handles may contain "." and "-" (first.last), which makes a trailing one
 * ambiguous: in "@grace." the dot is sentence punctuation, but in "@first.last"
 * it is part of the handle. Resolve it by looking one further — a dot or dash
 * NOT followed by a word character is punctuation.
 */
function boundaryAfter(text: string, i: number): boolean {
  const ch = text[i]
  if (ch === undefined) return true
  if (!HANDLE_CHAR.test(ch)) return true
  if (ch === "." || ch === "-") {
    const next = text[i + 1]
    return next === undefined || !/\w/.test(next)
  }
  return false
}

/**
 * Extract the ids mentioned in text.
 *
 * Handles are matched at word boundaries and de-duplicated, so editing a
 * mention out of the text removes the notification with it.
 */
export function extractIds(text: string, people: readonly Person[]): string[] {
  if (!text) return []

  // Longest handle first, so "@ada" inside "@adalovelace" cannot shadow it.
  const sorted = [...people].sort((a, b) => b.handle.length - a.handle.length)

  const found: Array<{ id: string; at: number }> = []
  const claimed: Array<[number, number]> = []

  for (const p of sorted) {
    const needle = `@${p.handle}`
    let from = 0
    for (;;) {
      const at = text.indexOf(needle, from)
      if (at === -1) break
      from = at + needle.length

      const beforeOk = at === 0 || !HANDLE_CHAR.test(text[at - 1]!)
      const afterOk = boundaryAfter(text, at + needle.length)
      const overlaps = claimed.some(([s, e]) => at < e && at + needle.length > s)

      if (beforeOk && afterOk && !overlaps) {
        claimed.push([at, at + needle.length])
        found.push({ id: p.id, at })
      }
    }
  }

  // First-appearance order, de-duplicated.
  found.sort((a, b) => a.at - b.at)
  const seen = new Set<string>()
  const out: string[] = []
  for (const f of found) {
    if (!seen.has(f.id)) {
      seen.add(f.id)
      out.push(f.id)
    }
  }
  return out
}

/** Build a value from text, recomputing ids so the two can never disagree. */
export function makeValue(text: string, people: readonly Person[]): MentionValue {
  return { text, ids: extractIds(text, people) }
}

/** Initials for an avatar. "Ada Lovelace" → "AL". */
export function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return "?"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return (parts[0]![0]! + parts.at(-1)![0]!).toUpperCase()
}

/** Smart paste — scrub clipboard junk, keep the text as written. */
export function parsePastedMention(
  input: string,
  people: readonly Person[],
): MentionValue | null {
  const text = scrub(input)
  if (!text) return null
  return makeValue(text, people)
}
